<?php
declare(strict_types=1);
use App\Core\Request;use App\Repositories\{AcademicRepository,AccountRepository,AttendanceRepository,EmployeeRepository,FeeRepository,SettingsRepository,StudentRepository,UserRepository};use App\Services\{AttendanceService,FeeService,StudentService};
return static function(\App\Core\App$app):array{$c=[];$db=$app->database();$i=(int)(new SettingsRepository($db))->institute()['id'];$ctx=(new UserRepository($db))->findAuthContext(1);$app->session()->set('auth_user',$ctx);$suffix=bin2hex(random_bytes(4));$academic=new AcademicRepository($db);$className='Priority QA '.$suffix;$c['priority class dependency']=$academic->createClass($i,$className,1000,null);$class=array_values(array_filter($academic->classes($i),fn($x)=>$x['name']===$className))[0];
$students=new StudentRepository($db);$ss=new StudentService($students);$reg='QA-'.$suffix;$data=$ss->data(['studentname'=>'QA Student','reg'=>$reg,'doa'=>date('Y-m-d'),'class'=>$class['id'],'discount'=>10,'fname'=>'QA Father','fi'=>50000,'mname'=>'QA Mother','mi'=>40000],$i);$sid=$ss->create($data);$student=$students->find($sid,$i);$c['full student created']=$student&&$student['father_name']==='QA Father'&&$student['mother_name']==='QA Mother';$c['student search']=$students->paginate($i,$reg)[0]['id']===$sid;try{$ss->create($data);$c['duplicate registration rejected']=false;}catch(PDOException){$c['duplicate registration rejected']=true;}$ss->update($sid,$i,['student_name'=>'QA Student Edited','updated_at'=>date('Y-m-d H:i:s')]);$c['student edit persisted']=$students->find($sid,$i)['student_name']==='QA Student Edited';
$employees=new EmployeeRepository($db);$now=date('Y-m-d H:i:s');$eid=$employees->create(['institute_id'=>$i,'employee_no'=>'EMP-'.$suffix,'name'=>'QA Employee','picture_path'=>null,'mobile'=>'03000000000','joining_date'=>date('Y-m-d'),'role'=>'Teacher','monthly_salary'=>50000,'show_on_profile'=>0,'father_husband_name'=>'QA Parent','national_id'=>null,'education'=>'Masters','gender'=>'Male','religion'=>null,'blood_group'=>null,'experience'=>'5 years','email'=>'qa-'.$suffix.'@example.test','date_of_birth'=>null,'home_address'=>'QA Address','status'=>'active','created_at'=>$now,'updated_at'=>$now]);$employees->update($eid,$i,['name'=>'QA Employee Edited','updated_at'=>$now]);$c['employee create/edit']=$employees->find($eid,$i)['name']==='QA Employee Edited';
$ar=new AttendanceRepository($db);$as=new AttendanceService($ar);$date=date('Y-m-d');$as->saveStudents($date,[$sid],[$sid=>'Absent'],[$sid=>'QA'],1);$as->saveStudents($date,[$sid],[$sid=>'Present'],[$sid=>'Updated'],1);$c['student attendance upsert']=$ar->students((int)$class['id'],$date,$i)[0]['attendance_status']==='Present';$as->saveEmployees($date,[$eid],[$eid=>'Late'],[$eid=>'08:15'],[$eid=>'16:00'],[$eid=>'QA'],1);$as->saveEmployees($date,[$eid],[$eid=>'Present'],[$eid=>'08:00'],[$eid=>'16:00'],[$eid=>'Updated'],1);$c['employee attendance upsert']=(array_column($ar->employees($date,$i),'attendance_status','id')[$eid]??null)==='Present';
$accounts=new AccountRepository($db);$income=$accounts->create($i,'income',$date,'QA Income '.$suffix,500,1,'QA-I');$expense=$accounts->create($i,'expense',$date,'QA Expense '.$suffix,125,1,'QA-E');$ledger=$accounts->statement($i,$date,$date,$suffix);$c['unified ledger stores income expense']=count($ledger)===2&&array_sum(array_map(fn($x)=>$x['transaction_type']==='income'?(float)$x['amount']:-(float)$x['amount'],$ledger))===375.0;
$fees=new FeeRepository($db);$fs=new FeeService($fees,$students);$month=date('Y-m');$invoice=$fs->ensureInvoice($student,$i,$month,1);$c['invoice calculated server side']=(float)$invoice['subtotal']>=1000&&(float)$invoice['discount']>0;$half=round((float)$invoice['total_amount']/2,2);$p1=$fs->collect($student,$i,$month,$half,'Cash','QA-1',1);$remaining=(float)$fees->invoice($sid,$month)['remaining_amount'];$p2=$fs->collect($student,$i,$month,$remaining,'Bank Transfer','QA-2',1);$final=$fees->invoice($sid,$month);$c['partial payments preserved']=count($fees->payments((int)$final['id']))===2;$c['invoice becomes paid']=$final['status']==='paid'&&(float)$final['remaining_amount']===0.0;$c['receipt persisted']=$fees->receipt($p1,$i)['receipt_no']!=='';$c['paid invoice leaves outstanding']=count(array_filter($fees->outstanding($i),fn($x)=>$x['id']===$final['id']))===0;
$req=fn($m,$u,$b=[])=>new Request([],$b,[],['REQUEST_METHOD'=>$m,'REQUEST_URI'=>$u]);$c['priority CSRF enforced']=$app->run($req('POST','/admin/accounts/income',['expensedate'=>$date,'expensedes'=>'x','expenseamt'=>1,'_token'=>'bad']))->status()===419;
$db->query('DELETE FROM fee_payments WHERE student_id=:id',['id'=>$sid]);$db->query('DELETE FROM fee_invoices WHERE student_id=:id',['id'=>$sid]);$db->query('DELETE FROM account_transactions WHERE id IN (:a,:b)',['a'=>$income,'b'=>$expense]);$db->query('DELETE FROM employees WHERE id=:id',['id'=>$eid]);$db->query('DELETE FROM students WHERE id=:id',['id'=>$sid]);$db->query('DELETE FROM classes WHERE id=:id',['id'=>$class['id']]);return$c;};
